-- [métier] = { ["i123"] = true, ["s456"] = true }
local speciales = {}
for code, d in pairs(DONNEES) do
	local t = {}
	for id in d.i:gmatch("%d+") do t["i" .. id] = true end
	for id in d.s:gmatch("%d+") do t["s" .. id] = true end
	speciales[code] = t
end

-- Recette apprise avec un plan ? (code de recette du registre : « i<objet> » ou « s<sort> »)
ns.RecetteDePlan = function(metier, code)
	local t = speciales[metier]
	return t ~= nil and t[code] == true
end
